#include <string.h>
#include <pcre2.h>

struct log_line {
  char level[16];
  char message[256];
};

static void copy_group(char *dst, size_t cap, const char *line, const PCRE2_SIZE *ov, int i) {
  size_t len = ov[2 * i + 1] - ov[2 * i];
  if (len >= cap) len = cap - 1;
  memcpy(dst, line + ov[2 * i], len);
  dst[len] = '\0';
}

int parse_log_line(const char *line, struct log_line *out) {
  int errcode;
  PCRE2_SIZE erroffset;
  pcre2_code *re = pcre2_compile((PCRE2_SPTR)"^([A-Z]+): (.*)$", PCRE2_ZERO_TERMINATED, 0, &errcode, &erroffset, NULL);
  if (re == NULL) return -1;
  pcre2_match_data *md = pcre2_match_data_create_from_pattern(re, NULL);
  if (md == NULL) {
    pcre2_code_free(re);
    return -1;
  }
  int rc = pcre2_match(re, (PCRE2_SPTR)line, PCRE2_ZERO_TERMINATED, 0, 0, md, NULL);
  if (rc > 0) {
    const PCRE2_SIZE *ov = pcre2_get_ovector_pointer(md);
    copy_group(out->level, sizeof out->level, line, ov, 1);
    copy_group(out->message, sizeof out->message, line, ov, 2);
  }
  pcre2_match_data_free(md);
  pcre2_code_free(re);
  if (rc == PCRE2_ERROR_NOMATCH) return 0;
  return rc > 0 ? 1 : -1;
}
